<script setup lang="ts">
import { ref,computed } from 'vue'
import { api } from '../../api'
import { usePage,perform,busy,user } from '../../state'
import type { Row } from '../../domain'
import PageHeader from '../../components/PageHeader.vue'
import DataTable from '../../components/DataTable.vue'
import LoadState from '../../components/LoadState.vue'
import OperationForm from '../../components/OperationForm.vue'
const tab=ref('offering'),funds=ref<Row[]>([]),dividends=ref<Row[]>([]),income=ref<Row[]>([]),pairs=ref<Row[]>([]),liquidations=ref<Row[]>([])
const {loading,error,load}=usePage(async()=>{[funds.value,dividends.value,income.value,pairs.value,liquidations.value]=await Promise.all([api.get('/admin/funds'),api.get('/admin/dividends'),api.get('/admin/money-income'),api.get('/admin/conversion-pairs'),api.get('/admin/liquidations')])})
const products=computed(()=>funds.value.map(f=>({value:f.id,label:f.name})))
const moneyProducts=computed(()=>funds.value.filter(f=>f.type==='MONEY').map(f=>({value:f.id,label:f.name})))
const netProducts=computed(()=>funds.value.filter(f=>f.type!=='MONEY').map(f=>({value:f.id,label:f.name})))
const raisingProducts=computed(()=>funds.value.filter(f=>f.state==='RAISING').map(f=>({value:f.id,label:f.name})))
async function dividendAction(row:Row,action:string){await perform(()=>api.post('/admin/dividends/'+row.id+'/'+action),load)}
function numeric(value:Row){return {...value,fundClassId:Number(value.fundClassId)}}
</script>
<template><PageHeader title="收益与生命周期" subtitle="募集、分红、货币收益、转换与清盘保持逐账户来源。"><button class="button" @click="load">刷新</button></PageHeader><LoadState :loading="loading" :error="error" @retry="load"/><div class="tabs"><button v-for="t in [['offering','募集结果'],['dividends','分红'],['money','货币收益'],['pairs','转换关系'],['liquidation','终止与清盘']]" :key="t[0]" :class="{active:tab===t[0]}" @click="tab=t[0]">{{ t[1] }}</button></div><template v-if="tab==='offering'"><OperationForm title="募集成立或失败" :fields="[{key:'fundId',label:'募集产品',type:'select',options:raisingProducts}, {key:'outcome',label:'募集结果',type:'select',options:[{value:'ESTABLISHED',label:'成立并登记份额'},{value:'FAILED',label:'失败并原路退款'}]}, {key:'endDate',label:'募集结束日期',type:'date'}, {key:'initialNav',label:'成立初始净值'}, {key:'interestRate',label:'募集年利率（小数）',hint:'默认0；按365天基数计算模拟利息'}]" :initial="{fundId:raisingProducts[0]?.value||'',outcome:'ESTABLISHED',endDate:'2026-10-14',initialNav:'1.000000',interestRate:'0'}" :submit="value=>api.post('/admin/offerings/'+value.fundId+'/finalize',{outcome:value.outcome,endDate:value.endDate,initialNav:value.initialNav,interestRate:value.interestRate})" button="执行募集结果" description="成立核销认购在途并形成份额；失败形成本金加利息的退款应付款，收款受阻时继续等待。" @saved="load"/><section class="panel"><h2>产品生命周期</h2><DataTable :rows="funds" :columns="[{key:'name',label:'基金'}, {key:'state',label:'运作状态',kind:'state'}, {key:'purchaseOpen',label:'申购开放',kind:'bool'}, {key:'redemptionOpen',label:'赎回开放',kind:'bool'}]"/></section></template><template v-else-if="tab==='dividends'"><OperationForm title="建立分红事件" :fields="[{key:'fundClassId',label:'基金类别',type:'select',options:netProducts}, {key:'recordDate',label:'权益登记日',type:'date'}, {key:'exDate',label:'除息日',type:'date'}, {key:'paymentDate',label:'支付日',type:'date'}, {key:'perShare',label:'每份分红（元）'}]" :initial="{fundClassId:netProducts[0]?.value||'',recordDate:'2026-10-13',exDate:'2026-10-14',paymentDate:'2026-10-15',perShare:'0.020000'}" :submit="value=>api.post('/admin/dividends',numeric(value))" description="登记日既有交易确认完毕后，次日生成权益快照。除息后净值由后台发布，程序不会重复扣净值。" @saved="load"/><section class="panel"><h2>分红事件与权益处理</h2><DataTable :rows="dividends" :columns="[{key:'id',label:'事件'}, {key:'fundName',label:'产品'}, {key:'recordDate',label:'登记日'}, {key:'exDate',label:'除息日'}, {key:'paymentDate',label:'支付日'}, {key:'perShare',label:'每份分红',kind:'nav'}, {key:'status',label:'状态',kind:'state'}]"><template #actions="{row}"><button class="text-button" :disabled="busy>0" @click="dividendAction(row,'snapshot')">生成权益快照</button><button class="text-button" :disabled="busy>0" @click="dividendAction(row,'execute')">执行分红</button></template></DataTable></section></template><template v-else-if="tab==='money'"><OperationForm title="发布自然日货币收益" :fields="[{key:'fundClassId',label:'货币基金',type:'select',options:moneyProducts}, {key:'date',label:'收益所属日期',type:'date'}, {key:'incomePerTenThousand',label:'每日万份收益（元）',hint:'支持负值，每日结转最多一次'}, {key:'annualYield',label:'七日年化（小数）',hint:'0.018代表1.8%，仅作为展示指标'}]" :initial="{fundClassId:moneyProducts[0]?.value||'',date:'2026-10-13',incomePerTenThousand:'0.480000',annualYield:'0.0175'}" :submit="value=>api.post('/admin/money-income',numeric(value))" description="录入后通过任务中心MONEY或ALL执行到期结转，包含周末自然日。" @saved="load"/><section class="panel"><DataTable :rows="income" :columns="[{key:'fundName',label:'产品'}, {key:'fundClassId',label:'类别'}, {key:'date',label:'收益日期'}, {key:'incomePerTenThousand',label:'万份收益（元）',kind:'nav'}, {key:'annualYield',label:'七日年化',kind:'percent'}]"/></section></template><template v-else-if="tab==='pairs'"><OperationForm title="配置支持转换组合" :fields="[{key:'sourceClassId',label:'转出产品',type:'select',options:netProducts}, {key:'targetClassId',label:'转入产品',type:'select',options:netProducts}, {key:'enabled',label:'启用此方向转换',type:'checkbox',required:false}]" :initial="{sourceClassId:netProducts[0]?.value||'',targetClassId:netProducts[1]?.value||'',enabled:true}" :submit="value=>api.post('/admin/conversion-pairs',{sourceClassId:Number(value.sourceClassId),targetClassId:Number(value.targetClassId),enabled:value.enabled})" description="每个方向独立配置，限同管理人、同渠道净值产品，不支持货币基金转换。" @saved="load"/><section class="panel"><DataTable :rows="pairs" :columns="[{key:'sourceName',label:'转出产品'}, {key:'sourceClassId',label:'转出类别ID'}, {key:'targetName',label:'转入产品'}, {key:'targetClassId',label:'转入类别ID'}, {key:'enabled',label:'已启用',kind:'bool'}]"/></section></template><template v-else><OperationForm v-if="user?.role==='ADMIN'" title="终止基金交易" :fields="[{key:'fundClassId',label:'基金',type:'select',options:products}, {key:'reason',label:'终止理由',type:'textarea'}]" :initial="{fundClassId:'',reason:''}" :submit="value=>api.post('/admin/funds/'+value.fundClassId+'/terminate',{reason:value.reason})" button="记录并终止" description="禁止新业务、停止未来定投，必须先处置未确认订单及未支付款。" @saved="load"/><OperationForm v-if="user?.role==='ADMIN'" title="执行清盘分配" :fields="[{key:'fundClassId',label:'基金',type:'select',options:products}, {key:'perShare',label:'最终每份清算分配额（元）'}, {key:'date',label:'清盘日期',type:'date'}, {key:'reason',label:'分配说明',type:'textarea'}]" :initial="{fundClassId:'',perShare:'',date:'2026-10-19',reason:''}" :submit="value=>api.post('/admin/liquidations',numeric(value))" button="逐账户核销并形成回款" description="未完成业务及收益结转会阻止清盘；回款受阻仍保留清盘应收资产。" @saved="load"/><section class="panel"><h2>清盘记录</h2><DataTable :rows="liquidations" :columns="[{key:'id',label:'事件'}, {key:'fundName',label:'基金'}, {key:'fundClassId',label:'类别'}, {key:'date',label:'清盘日期'}, {key:'perShare',label:'每份分配（元）',kind:'nav'}, {key:'status',label:'状态',kind:'state'}, {key:'reason',label:'说明'}]"/></section></template></template>
